{"command":"cat <<'EOF' > tmp/cgo_test.go
package main

/*
#cgo LDFLAGS: -lsqlite3
#include <sqlite3.h>
#include <stdlib.h>
*/
import "C"
import (
	"fmt"
	"unsafe"
)

type DB struct {
	db *C.sqlite3
}

func OpenDB(dsn string) (*DB, error) {
	if dsn == "" {
		dsn = ":memory:"
	}
	cdsn := C.CString(dsn)
	defer C.free(unsafe.Pointer(cdsn))
	var db *C.sqlite3
	if C.sqlite3_open(cdsn, &db) != C.SQLITE_OK {
		msg := C.GoString(C.sqlite3_errmsg(db))
		C.sqlite3_close(db)
		return nil, fmt.Errorf("sqlite error: %s", msg)
	}
	return &DB{db: db}, nil
}

func (d *DB) Exec(sqlStr string) error {
	csql := C.CString(sqlStr)
	defer C.free(unsafe.Pointer(csql))
	var errmsg *C.char
	if C.sqlite3_exec(d.db, csql, nil, nil, &errmsg) != C.SQLITE_OK {
		msg := C.GoString(errmsg)
		C.sqlite3_free(unsafe.Pointer(errmsg))
		return fmt.Errorf("exec error: %s", msg)
	}
	return nil
}

func (d *DB) Query(sqlStr string) ([]string, [][]string, error) {
	csql := C.CString(sqlStr)
	defer C.free(unsafe.Pointer(csql))
	var stmt *C.sqlite3_stmt
	if C.sqlite3_prepare_v2(d.db, csql, -1, &stmt, nil) != C.SQLITE_OK {
		msg := C.GoString(C.sqlite3_errmsg(d.db))
		return nil, nil, fmt.Errorf("prepare error: %s", msg)
	}
	defer C.sqlite3_finalize(stmt)

	colCount := int(C.sqlite3_column_count(stmt))
	cols := make([]string, colCount)
	for i := 0; i < colCount; i++ {
		cols[i] = C.GoString((*C.char)(unsafe.Pointer(C.sqlite3_column_name(stmt, C.int(i)))))
	}

	var rows [][]string
	for {
		res := C.sqlite3_step(stmt)
		if res == C.SQLITE_DONE {
			break
		}
		if res != C.SQLITE_ROW {
			msg := C.GoString(C.sqlite3_errmsg(d.db))
			return nil, nil, fmt.Errorf("step error: %s", msg)
		}
		row := make([]string, colCount)
		for i := 0; i < colCount; i++ {
			if C.sqlite3_column_type(stmt, C.int(i)) == C.SQLITE_NULL {
				row[i] = "" // or null representation
			} else {
				val := C.sqlite3_column_text(stmt, C.int(i))
				row[i] = C.GoString((*C.char)(unsafe.Pointer(val)))
			}
		}
		rows = append(rows, row)
	}
	return cols, rows, nil
}

func main() {
	db, err := OpenDB("")
	if err != nil {
		panic(err)
	}
	err = db.Exec("CREATE TABLE t (id INT, name TEXT)")
	if err != nil {
		panic(err)
	}
	err = db.Exec("INSERT INTO t VALUES (1, 'Alice'), (2, 'Bob')")
	if err != nil {
		panic(err)
	}
	cols, rows, err := d.Query("SELECT * FROM t")
	if err != nil {
		panic(err)
	}
	fmt.Println("Cols:", cols)
	for _, r := range rows {
		fmt.Println("Row:", r)
	}
}
EOF

go run tmp/cgo_test.go"}

