			msg := C.GoString(C.sqlite3_errmsg(d.db))
			return nil, fmt.Errorf("%s [%s]", msg, sqlStr)
		}
		row := make([]interface{}, colCount)
		for i := 0; i < colCount; i++ {
			cType := C.sqlite3_column_type(stmt, C.int(i))
			switch cType {
			case C.SQLITE_NULL:
				row[i] = nil
			case C.SQLITE_INTEGER:
				row[i] = int64(C.sqlite3_column_int64(stmt, C.int(i)))
			case C.SQLITE_FLOAT:
				row[i] = float64(C.sqlite3_column_double(stmt, C.int(i)))
			default:
				val := C.sqlite3_column_text(stmt, C.int(i))
				row[i] = C.GoString((*C.char)(unsafe.Pointer(val)))
			}
		}
		rows = append(rows, row)
	}
	return &QueryResult{
		Columns: cols,
		Types:   types,
		Rows:    rows,
	}, nil
}
EOF"}

