	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

type InputFormat int

const (
	FormatCSV InputFormat = iota
	FormatTSV
	FormatPSV
	FormatLTSV
	FormatJSON
	FormatYAML
	FormatTBLN
	FormatTEXT
	FormatWIDTH
)

type ImportOptions struct {
	InFormat  InputFormat
	HasInFmt  bool
	Delimiter string
	Header    bool
	Jq        string
	LimitRead int
	InNull    string
	InNullSet bool
	AddNum    bool
	PreRead   int
	Skip      int
	Guess     bool
}

func logPrint(msg string) {
	now := fmt.Sprintf("%04d/%02d/%02d %02d:%02d:%02d",
		2026, 7, 31, 1, 57, 38) // we will use real time in main or log package
	fmt.Fprintf(os.Stderr, "%s %s\n", now, msg)
}

func GuessInputFormat(filename string) InputFormat {
	base := filepath.Base(filename)
	ext := strings.ToLower(filepath.Ext(base))
	if ext == ".gz" || ext == ".bz2" || ext == ".xz" || ext == ".zst" || ext == ".zstd" {
		base = base[:len(base)-len(ext)]
		ext = strings.ToLower(filepath.Ext(base))
	}
	switch ext {
	case ".csv":
		return FormatCSV
	case ".tsv", ".tab":
		return FormatTSV
	case ".psv":
		return FormatPSV
	case ".ltsv":
		return FormatLTSV
	case ".json", ".jsonl", ".ndjson":
		return FormatJSON
	case ".yaml", ".yml":
		return FormatYAML
	case ".tbln":
		return FormatTBLN
	case ".txt":
		return FormatTEXT
	default:
		return FormatCSV
	}
}

func OpenInputFile(filename string) (io.ReadCloser, string, error) {
	if filename == "-" {
		return io.NopCloser(os.Stdin), "-", nil
	}
	f, err := os.Open(filename)
	if err != nil {
		return nil, "", err
	}

	ext := strings.ToLower(filepath.Ext(filename))
	switch ext {
	case ".gz":
		gz, err := gzip.NewReader(f)
		if err != nil {
			f.Close()
			return nil, "", err
		}
		return gz, filename, nil
	case ".bz2":
		bz := bzip2.NewReader(f)
		return struct {
			io.Reader
			io.Closer
		}{bz, f}, filename, nil
	case ".xz":
		cmd := exec.Command("xzcat", filename)
		out, err := cmd.StdoutPipe()
		if err != nil {
			f.Close()
			return nil, "", err
		}
		if err := cmd.Start(); err != nil {
			f.Close()
			return nil, "", err
		}
		return struct {
			io.Reader
			io.Closer
		}{out, f}, filename, nil
	default:
		return f, filename, nil
	}
}

// EvaluateSimpleJQ evaluates basic JQ expressions like .data, .items, .data[], .[0]
func EvaluateSimpleJQ(data interface{}, jq string) interface{} {
	jq = strings.TrimSpace(jq)
	if jq == "" || jq == "." {
		return data
	}

	parts := strings.Split(jq, ".")
	curr := data

	for _, p := range parts {
		if p == "" {
			continue
		}
		p = strings.TrimSuffix(p, "[]")

		// Check for array indexing like [0] or name[0]
		if idx := strings.Index(p, "["); idx != -1 && strings.HasSuffix(p, "]") {
			key := p[:idx]
			idxStr := p[idx+1 : len(p)-1]
			index, err := strconv.Atoi(idxStr)

			if key != "" {
				if m, ok := curr.(map[string]interface{}); ok {
					curr = m[key]
				} else {
					return nil
				}
			}

			if arr, ok := curr.([]interface{}); ok && err == nil {
				if index >= 0 && index < len(arr) {
					curr = arr[index]
				} else {
					return nil
				}
			} else {
				return nil
			}
		} else {
			if m, ok := curr.(map[string]interface{}); ok {
				curr = m[p]
			} else if arr, ok := curr.([]interface{}); ok {
				var newArr []interface{}
				for _, item := range arr {
					if mItem, ok := item.(map[string]interface{}); ok {
						if val, exists := mItem[p]; exists {
							if valArr, isArr := val.([]interface{}); isArr {
								newArr = append(newArr, valArr...)
							} else {
								newArr = append(newArr, val)
							}
						}
					}
				}
				curr = newArr
			} else {
				return nil
			}
		}
	}
	return curr
}

type ParsedTable struct {
	ColNames []string
	Rows     [][]interface{}
}

func ReadTableData(r io.Reader, filename string, opts ImportOptions, debug bool) (*ParsedTable, error) {
	format := opts.InFormat
	if !opts.HasInFmt && opts.Guess {
		format = GuessInputFormat(filename)
		if debug {
			switch format {
			case FormatCSV:
				if strings.HasSuffix(filename, ".tsv") || strings.HasSuffix(filename, ".tab") {
					logPrint(fmt.Sprintf("Guess file type as TSV: [%s]", filename))
				} else if strings.HasSuffix(filename, ".psv") {
					logPrint(fmt.Sprintf("Guess file type as PSV: [%s]", filename))
				} else {
					if !strings.HasSuffix(filename, ".csv") {
						logPrint(fmt.Sprintf("Set in CSV because the extension is unknown: [%s]", filename))
					}
					logPrint(fmt.Sprintf("Guess file type as CSV: [%s]", filename))
				}
			case FormatLTSV:
				logPrint(fmt.Sprintf("Guess file type as LTSV: [%s]", filename))
			case FormatJSON:
				logPrint(fmt.Sprintf("Guess file type as JSON: [%s]", filename))
			case FormatYAML:
				logPrint(fmt.Sprintf("Guess file type as YAML: [%s]", filename))
			case FormatTBLN:
				logPrint(fmt.Sprintf("Guess file type as TBLN: [%s]", filename))
			case FormatTEXT:
				logPrint(fmt.Sprintf("Guess file type as TEXT: [%s]", filename))
			}
		}
	}

	bufReader := bufio.NewReader(r)

	// Skip header lines
	for i := 0; i < opts.Skip; i++ {
		_, err := bufReader.ReadString('\n')
		if err != nil && err != io.EOF {
			return nil, err
		}
	}

	var cols []string
	var rawRows [][]interface{}

	switch format {
	case FormatCSV, FormatTSV, FormatPSV:
		delim := ','
		if opts.Delimiter != "" && opts.Delimiter != "," {
			delim = []rune(opts.Delimiter)[0]
		} else if format == FormatTSV {
			delim = '\t'
		} else if format == FormatPSV {
			delim = '|'
		}

		csvReader := csv.NewReader(bufReader)
		csvReader.Comma = delim
		csvReader.FieldsPerRecord = -1

		records, err := csvReader.ReadAll()
		if err != nil && len(records) == 0 {
			return nil, err
		}

		if len(records) > 0 {
			if opts.Header {
				cols = records[0]
				records = records[1:]
			} else {
				numCols := len(records[0])
				cols = make([]string, numCols)
				for i := 0; i < numCols; i++ {
					cols[i] = fmt.Sprintf("c%d", i+1)
				}
			}

			for _, rec := range records {
				row := make([]interface{}, len(rec))
				for i, val := range rec {
					if opts.InNullSet && val == opts.InNull {
						row[i] = nil
					} else {
						row[i] = val
					}
				}
				rawRows = append(rawRows, row)
			}
		}

	case FormatLTSV:
		scanner := bufio.NewScanner(bufReader)
		var keyOrder []string
		keySet := make(map[string]bool)
		var parsedLines []map[string]string

		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if line == "" {
				continue
			}
			parts := strings.Split(line, "\t")
			entry := make(map[string]string)
			for _, part := range parts {
				kv := strings.SplitN(part, ":", 2)
				if len(kv) == 2 {
					k, v := kv[0], kv[1]
					entry[k] = v
					if !keySet[k] {
						keySet[k] = true
						keyOrder = append(keyOrder, k)
					}
				}
			}
			parsedLines = append(parsedLines, entry)
		}

		cols = keyOrder
		for _, entry := range parsedLines {
			row := make([]interface{}, len(cols))
			for i, k := range cols {
				if val, exists := entry[k]; exists {
					if opts.InNullSet && val == opts.InNull {
						row[i] = nil
					} else {
						row[i] = val
					}
				} else {
					row[i] = nil
				}
			}
			rawRows = append(rawRows, row)
		}

	case FormatJSON:
		content, err := io.ReadAll(bufReader)
		if err != nil {
			return nil, err
		}

		var jsonObj interface{}
		err = json.Unmarshal(content, &jsonObj)
		if err != nil {
			// Try JSON Lines
			lines := strings.Split(string(content), "\n")
			var list []interface{}
			for _, l := range lines {
				l = strings.TrimSpace(l)
				if l == "" {
					continue
				}
				var item interface{}
				if err2 := json.Unmarshal([]byte(l), &item); err2 == nil {
					list = append(list, item)
				}
			}
			jsonObj = list
		}

		if opts.Jq != "" {
			jsonObj = EvaluateSimpleJQ(jsonObj, opts.Jq)
		}

		var items []interface{}
		if arr, ok := jsonObj.([]interface{}); ok {
			items = arr
		} else if jsonObj != nil {
			items = append(items, jsonObj)
		}

		var keyOrder []string
		keySet := make(map[string]bool)

		for _, item := range items {
			if m, ok := item.(map[string]interface{}); ok {
				for k := range m {
					if !keySet[k] {
						keySet[k] = true
						keyOrder = append(keyOrder, k)
					}
				}
			}
		}

		if len(keyOrder) == 0 {
			cols = []string{"c1"}
			for _, item := range items {
				valStr := fmt.Sprintf("%v", item)
				if opts.InNullSet && valStr == opts.InNull {
					rawRows = append(rawRows, []interface{}{nil})
				} else {
					rawRows = append(rawRows, []interface{}{valStr})
				}
			}
		} else {
			cols = keyOrder
			for _, item := range items {
				row := make([]interface{}, len(cols))
				if m, ok := item.(map[string]interface{}); ok {
					for i, k := range cols {
						if val, exists := m[k]; exists && val != nil {
							switch v := val.(type) {
							case map[string]interface{}, []interface{}:
								b, _ := json.Marshal(v)
								row[i] = string(b)
							default:
								s := fmt.Sprintf("%v", v)
								if opts.InNullSet && s == opts.InNull {
									row[i] = nil
								} else {
									row[i] = s
								}
							}
						} else {
							row[i] = nil
						}
					}
				}
				rawRows = append(rawRows, row)
			}
		}

	case FormatYAML:
		content, err := io.ReadAll(bufReader)
		if err != nil {
			return nil, err
		}
		var yamlObj interface{}
		err = yaml.Unmarshal(content, &yamlObj)
		if err != nil {
			return nil, err
		}

		if opts.Jq != "" {
			yamlObj = EvaluateSimpleJQ(yamlObj, opts.Jq)
		}

		var items []interface{}
		if arr, ok := yamlObj.([]interface{}); ok {
			items = arr
		} else if yamlObj != nil {
			items = append(items, yamlObj)
		}

		var keyOrder []string
		keySet := make(map[string]bool)

		for _, item := range items {
			if m, ok := item.(map[string]interface{}); ok {
				for k := range m {
					if !keySet[k] {
						keySet[k] = true
						keyOrder = append(keyOrder, k)
					}
				}
			}
		}

		cols = keyOrder
		for _, item := range items {
			row := make([]interface{}, len(cols))
			if m, ok := item.(map[string]interface{}); ok {
				for i, k := range cols {
					if val, exists := m[k]; exists && val != nil {
						s := fmt.Sprintf("%v", val)
						if opts.InNullSet && s == opts.InNull {
							row[i] = nil
						} else {
							row[i] = s
						}
					} else {
						row[i] = nil
					}
				}
			}
			rawRows = append(rawRows, row)
		}

	case FormatTBLN:
		scanner := bufio.NewScanner(bufReader)
		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if strings.HasPrefix(line, ";") {
				if strings.Contains(line, "name:") || strings.Contains(line, "header:") {
					parts := strings.Split(line, "|")
					for _, p := range parts {
						p = strings.TrimSpace(p)
						if p != "" && !strings.HasPrefix(p, ";") {
							cols = append(cols, p)
						}
					}
				}
				continue
			}
			if strings.HasPrefix(line, "|") && strings.HasSuffix(line, "|") {
				parts := strings.Split(line[1:len(line)-1], "|")
				row := make([]interface{}, len(parts))
				for i, p := range parts {
					val := strings.TrimSpace(p)
					if opts.InNullSet && val == opts.InNull {
						row[i] = nil
					} else {
						row[i] = val
					}
				}
				rawRows = append(rawRows, row)
			}
		}

	case FormatTEXT:
		cols = []string{"text"}
		scanner := bufio.NewScanner(bufReader)
		for scanner.Scan() {
			val := scanner.Text()
			if opts.InNullSet && val == opts.InNull {
				rawRows = append(rawRows, []interface{}{nil})
			} else {
				rawRows = append(rawRows, []interface{}{val})
			}
		}

	case FormatWIDTH:
		var widths []int
		if opts.Delimiter != "" {
			parts := strings.Split(opts.Delimiter, ",")
			for _, p := range parts {
				w, _ := strconv.Atoi(strings.TrimSpace(p))
				if w > 0 {
					widths = append(widths, w)
				}
			}
		}

		scanner := bufio.NewScanner(bufReader)
		for scanner.Scan() {
			line := scanner.Text()
			var fields []string
			if len(widths) > 0 {
				pos := 0
				for _, w := range widths {
					if pos >= len(line) {
						fields = append(fields, "")
					} else if pos+w >= len(line) {
						fields = append(fields, strings.TrimSpace(line[pos:]))
					} else {
						fields = append(fields, strings.TrimSpace(line[pos:pos+w]))
					}
					pos += w
				}
			} else {
				fields = strings.Fields(line)
			}

			if len(cols) == 0 {
				cols = make([]string, len(fields))
				for i := 0; i < len(fields); i++ {
					cols[i] = fmt.Sprintf("c%d", i+1)
				}
			}

			row := make([]interface{}, len(cols))
			for i := 0; i < len(cols); i++ {
				if i < len(fields) {
					val := fields[i]
					if opts.InNullSet && val == opts.InNull {
						row[i] = nil
					} else {
						row[i] = val
					}
				} else {
					row[i] = nil
				}
			}
			rawRows = append(rawRows, row)
		}
	}

	// Apply LimitRead
	if opts.LimitRead > 0 && len(rawRows) > opts.LimitRead {
		rawRows = rawRows[:opts.LimitRead]
	}

	// Apply AddNum
	if opts.AddNum {
		cols = append([]string{"num"}, cols...)
		for i, r := range rawRows {
			rawRows[i] = append([]interface{}{i + 1}, r...)
		}
	}

	return &ParsedTable{
		ColNames: cols,
		Rows:     rawRows,
	}, nil
}

type TableImportInfo struct {
	OriginalName string
	ActualFile   string
	JqExpr       string
	ImportName   string
}

func ExtractTableNames(sqlStr string) []TableImportInfo {
	// Matches file references or table names in FROM, JOIN, INTO, UPDATE
	re := regexp.MustCompile(`(?i)\b(?:FROM|JOIN|INTO|UPDATE)\s+([\`'"a-zA-Z0-9_\-\.\/\:\=]+)`)
	matches := re.FindAllStringSubmatch(sqlStr, -1)

	var infos []TableImportInfo
	seen := make(map[string]bool)
	jqCount := 0

	for _, m := range matches {
		if len(m) < 2 {
			continue
		}
		raw := m[1]
		raw = strings.Trim(raw, "`")

		if seen[raw] {
			continue
		}
		seen[raw] = true

		actualFile := raw
		jqExpr := ""
		importName := raw

		if idx := strings.Index(raw, "::"); idx != -1 {
			actualFile = raw[:idx]
			jqExpr = raw[idx+2:]
			jqCount++
			importName = fmt.Sprintf("%s::jq%d", actualFile, jqCount)
		}

		infos = append(infos, TableImportInfo{
			OriginalName: raw,
			ActualFile:   actualFile,
			JqExpr:       jqExpr,
			ImportName:   importName,
		})
	}

	return infos
}

func ImportTables(db *DB, sqlStr string, opts ImportOptions, debug bool) (string, error) {
	infos := ExtractTableNames(sqlStr)
	transformedSQL := sqlStr

	for _, info := range infos {
		r, actualName, err := OpenInputFile(info.ActualFile)
		if err != nil {
			// If file does not exist, continue (might be SQLite system table or CTE)
			continue
		}

		tblOpts := opts
		if info.JqExpr != "" {
			tblOpts.Jq = info.JqExpr
		}

		parsed, err := ReadTableData(r, actualName, tblOpts, debug)
		r.Close()
		if err != nil {
			return "", err
		}

		if len(parsed.ColNames) == 0 {
			continue
		}

		if debug {
			logPrint(fmt.Sprintf("Column Names: [%s]", strings.Join(parsed.ColNames, ",")))
			colTypes := make([]string, len(parsed.ColNames))
			for i := range colTypes {
				colTypes[i] = "text"
			}
			logPrint(fmt.Sprintf("Column Types: [%s]", strings.Join(colTypes, ",")))
		}

		var colDefs []string
		var colNamesQuoted []string
		for _, col := range parsed.ColNames {
			colDefs = append(colDefs, fmt.Sprintf("`%s` text", col))
			colNamesQuoted = append(colNamesQuoted, fmt.Sprintf("`%s`", col))
		}

		createSQL := fmt.Sprintf("CREATE TEMPORARY TABLE `%s` ( %s );", info.ImportName, strings.Join(colDefs, ", "))
		if debug {
			logPrint(createSQL)
		}

		if err := db.Exec(createSQL); err != nil {
			return "", fmt.Errorf("create table error: %w", err)
		}

		placeholders := make([]string, len(parsed.ColNames))
		for i := range placeholders {
			placeholders[i] = "?"
		}

		insertSQL := fmt.Sprintf("INSERT INTO `%s` (%s) VALUES (%s);",
			info.ImportName,
			strings.Join(colNamesQuoted, ", "),
			strings.Join(placeholders, ","))

		if len(parsed.Rows) > 0 {
			stmt, err := db.Prepare(insertSQL)
			if err != nil {
				return "", fmt.Errorf("prepare insert error: %w", err)
			}
			err = stmt.ExecBatch(parsed.Rows)
			stmt.Close()
			if err != nil {
				return "", fmt.Errorf("insert error: %w", err)
			}
		}

		// Replace table reference in SQL query
		// First handle original name replace
		origQuoted := fmt.Sprintf("`%s`", info.ImportName)
		if info.OriginalName != info.ActualFile {
			transformedSQL = strings.ReplaceAll(transformedSQL, info.OriginalName, origQuoted)
		} else {
			// Replace raw filename or `filename`
			reRaw := regexp.MustCompile(fmt.Sprintf("`?%s`?", regexp.QuoteMeta(info.OriginalName)))
			transformedSQL = reRaw.ReplaceAllString(transformedSQL, origQuoted)
		}
	}

	return transformedSQL, nil
}
