type OutputFormat int

const (
	OutCSV OutputFormat = iota
	OutLTSV
	OutJSON
	OutJSONL
	OutYAML
	OutMD
	OutAT
	OutVF
	OutRAW
	OutTBLN
)

type ExportOptions struct {
	OutFormat OutputFormat
	AllQuotes bool
	CRLF      bool
	Delimiter string
	Header    bool
	NoWrap    bool
	OutNull   string
	OutNullSet bool
	QuoteChar string
	OutFile   string
	NoGuess   bool
	Compress  string
}

func GuessOutputFormat(filename string) (OutputFormat, string) {
	base := filepath.Base(filename)
	ext := strings.ToLower(filepath.Ext(base))
	compress := ""

	if ext == ".gz" || ext == ".bz2" || ext == ".xz" || ext == ".zst" || ext == ".zstd" {
		compress = ext[1:]
		base = base[:len(base)-len(ext)]
		ext = strings.ToLower(filepath.Ext(base))
	}

	switch ext {
	case ".csv":
		return OutCSV, compress
	case ".tsv", ".tab":
		return OutCSV, compress
	case ".ltsv":
		return OutLTSV, compress
	case ".json":
		return OutJSON, compress
	case ".jsonl", ".ndjson":
		return OutJSONL, compress
	case ".yaml", ".yml":
		return OutYAML, compress
	case ".md", ".markdown":
		return OutMD, compress
	case ".at":
		return OutAT, compress
	case ".vf":
		return OutVF, compress
	case ".raw":
		return OutRAW, compress
	case ".tbln":
		return OutTBLN, compress
	default:
		return OutCSV, compress
	}
}

func OpenOutputStream(opts ExportOptions) (io.WriteCloser, error) {
	var w io.WriteCloser = os.Stdout

	if opts.OutFile != "" {
		f, err := os.Create(opts.OutFile)
		if err != nil {
			return nil, err
		}
		w = f
	}

	compress := opts.Compress
	if opts.OutFile != "" && !opts.NoGuess && compress == "" {
		_, guessedComp := GuessOutputFormat(opts.OutFile)
		if guessedComp != "" {
			compress = guessedComp
		}
	}

	switch compress {
	case "gz", "gzip":
		return gzip.NewWriter(w), nil
	case "bz2", "bzip2":
		cmd := exec.Command("bzip2")
		cmd.Stdout = w
		in, err := cmd.StdinPipe()
		if err != nil {
			return nil, err
		}
		if err := cmd.Start(); err != nil {
			return nil, err
		}
		return &cmdWriter{pipe: in, cmd: cmd}, nil
	case "xz":
		cmd := exec.Command("xz")
		cmd.Stdout = w
		in, err := cmd.StdinPipe()
		if err != nil {
			return nil, err
		}
		if err := cmd.Start(); err != nil {
			return nil, err
		}
		return &cmdWriter{pipe: in, cmd: cmd}, nil
