	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

type OutputFormat int

const (
	OutCSV OutputFormat = iota
	OutLTSV
	OutJSON
	OutJSONL
	OutYAML
	OutMD
	OutAT
	OutVF
	OutRAW
	OutTBLN
)

type ExportOptions struct {
	OutFormat OutputFormat
	AllQuotes bool
	CRLF      bool
	Delimiter string
	Header    bool
	NoWrap    bool
	OutNull   string
	OutNullSet bool
	QuoteChar string
	OutFile   string
	NoGuess   bool
	Compress  string
}

func GuessOutputFormat(filename string) (OutputFormat, string) {
	base := filepath.Base(filename)
	ext := strings.ToLower(filepath.Ext(base))
	compress := ""

	if ext == ".gz" || ext == ".bz2" || ext == ".xz" || ext == ".zst" || ext == ".zstd" {
		compress = ext[1:]
		base = base[:len(base)-len(ext)]
		ext = strings.ToLower(filepath.Ext(base))
	}

	switch ext {
	case ".csv":
		return OutCSV, compress
	case ".tsv", ".tab":
		return OutCSV, compress
	case ".ltsv":
		return OutLTSV, compress
	case ".json":
		return OutJSON, compress
	case ".jsonl", ".ndjson":
		return OutJSONL, compress
	case ".yaml", ".yml":
		return OutYAML, compress
	case ".md", ".markdown":
		return OutMD, compress
	case ".at":
		return OutAT, compress
	case ".vf":
		return OutVF, compress
	case ".raw":
		return OutRAW, compress
	case ".tbln":
		return OutTBLN, compress
	default:
		return OutCSV, compress
	}
}

func OpenOutputStream(opts ExportOptions) (io.WriteCloser, error) {
	var w io.WriteCloser = os.Stdout

	if opts.OutFile != "" {
		f, err := os.Create(opts.OutFile)
		if err != nil {
			return nil, err
		}
		w = f
	}

	compress := opts.Compress
	if opts.OutFile != "" && !opts.NoGuess && compress == "" {
		_, guessedComp := GuessOutputFormat(opts.OutFile)
		if guessedComp != "" {
			compress = guessedComp
		}
	}

	switch compress {
	case "gz", "gzip":
		return gzip.NewWriter(w), nil
	case "bz2", "bzip2":
		cmd := exec.Command("bzip2")
		cmd.Stdout = w
		in, err := cmd.StdinPipe()
		if err != nil {
			return nil, err
		}
		if err := cmd.Start(); err != nil {
			return nil, err
		}
		return &cmdWriter{pipe: in, cmd: cmd}, nil
	case "xz":
		cmd := exec.Command("xz")
		cmd.Stdout = w
		in, err := cmd.StdinPipe()
		if err != nil {
			return nil, err
		}
		if err := cmd.Start(); err != nil {
			return nil, err
		}
		return &cmdWriter{pipe: in, cmd: cmd}, nil
	default:
		return w, nil
	}
}

type cmdWriter struct {
	pipe io.WriteCloser
	cmd  *exec.Cmd
}

func (c *cmdWriter) Write(p []byte) (int, error) {
	return c.pipe.Write(p)
}

func (c *cmdWriter) Close() error {
	c.pipe.Close()
	return c.cmd.Wait()
}

func FormatValue(val interface{}, outNull string, outNullSet bool) string {
	if val == nil {
		if outNullSet {
			return outNull
		}
		return ""
	}
	return fmt.Sprintf("%v", val)
}

func ExportResult(res *QueryResult, opts ExportOptions) error {
	w, err := OpenOutputStream(opts)
	if err != nil {
		return err
	}
	defer w.Close()

	eol := "\n"
	if opts.CRLF {
		eol = "\r\n"
	}

	outFormat := opts.OutFormat
	if opts.OutFile != "" && !opts.NoGuess {
		guessedFmt, _ := GuessOutputFormat(opts.OutFile)
		outFormat = guessedFmt
	}

	switch outFormat {
	case OutCSV:
		delim := ','
		if opts.Delimiter != "" {
			delim = []rune(opts.Delimiter)[0]
		}
		csvWriter := csv.NewWriter(w)
		csvWriter.Comma = delim
		csvWriter.UseCRLF = opts.CRLF

		if opts.Header {
			if err := csvWriter.Write(res.Columns); err != nil {
				return err
			}
		}

		for _, row := range res.Rows {
			record := make([]string, len(row))
			for i, val := range row {
				s := FormatValue(val, opts.OutNull, opts.OutNullSet)
				if opts.AllQuotes && val != nil {
					quote := "\""
					if opts.QuoteChar != "" {
						quote = opts.QuoteChar
					}
					s = quote + strings.ReplaceAll(s, quote, quote+quote) + quote
				}
				record[i] = s
			}
			if err := csvWriter.Write(record); err != nil {
				return err
			}
		}
		csvWriter.Flush()
		return csvWriter.Error()

	case OutLTSV:
		for _, row := range res.Rows {
			var parts []string
			for i, col := range res.Columns {
				s := FormatValue(row[i], opts.OutNull, opts.OutNullSet)
				parts = append(parts, fmt.Sprintf("%s:%s", col, s))
			}
			fmt.Fprintf(w, "%s%s", strings.Join(parts, "\t"), eol)
		}

	case OutJSON, OutJSONL:
		var items []map[string]interface{}
		for _, row := range res.Rows {
			item := make(map[string]interface{})
			for i, col := range res.Columns {
				val := row[i]
				if val == nil {
					if opts.OutNullSet {
						item[col] = opts.OutNull
					} else {
						item[col] = nil
					}
				} else {
					s := fmt.Sprintf("%v", val)
					// Try parsing s as JSON object/array
					if (strings.HasPrefix(s, "{") && strings.HasSuffix(s, "}")) ||
						(strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]")) {
						var parsed interface{}
						if err := json.Unmarshal([]byte(s), &parsed); err == nil {
							item[col] = parsed
							continue
						}
					}
					item[col] = val
				}
			}
			items = append(items, item)
		}

		if outFormat == OutJSONL {
			for _, item := range items {
				b, _ := json.Marshal(item)
				fmt.Fprintf(w, "%s%s", string(b), eol)
			}
		} else {
			b, _ := json.MarshalIndent(items, "", "  ")
			fmt.Fprintf(w, "%s%s", string(b), eol)
		}

	case OutYAML:
		var items []map[string]interface{}
		for _, row := range res.Rows {
			item := make(map[string]interface{})
			for i, col := range res.Columns {
				val := row[i]
				if val == nil {
					if opts.OutNullSet {
						item[col] = opts.OutNull
					} else {
						item[col] = nil
					}
				} else {
					s := fmt.Sprintf("%v", val)
					if (strings.HasPrefix(s, "{") && strings.HasSuffix(s, "}")) ||
						(strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]")) {
						var parsed interface{}
						if err := json.Unmarshal([]byte(s), &parsed); err == nil {
							item[col] = parsed
							continue
						}
					}
					item[col] = val
				}
			}
			items = append(items, item)
		}
		b, _ := yaml.Marshal(items)
		fmt.Fprintf(w, "%s", string(b))

	case OutRAW:
		delim := ","
		if opts.Delimiter != "" {
			delim = opts.Delimiter
		}
		for _, row := range res.Rows {
			var parts []string
			for _, val := range row {
				s := FormatValue(val, opts.OutNull, opts.OutNullSet)
				parts = append(parts, s)
			}
			fmt.Fprintf(w, "%s%s", strings.Join(parts, delim), eol)
		}

	case OutTBLN:
		var nameTypes []string
		for range res.Columns {
			nameTypes = append(nameTypes, "text")
		}
		fmt.Fprintf(w, "; name: | %s |%s", strings.Join(res.Columns, " | "), eol)
		fmt.Fprintf(w, "; type: | %s |%s", strings.Join(nameTypes, " | "), eol)

		for _, row := range res.Rows {
			var parts []string
			for _, val := range row {
				s := FormatValue(val, opts.OutNull, opts.OutNullSet)
				parts = append(parts, s)
			}
			fmt.Fprintf(w, "| %s |%s", strings.Join(parts, " | "), eol)
		}

	case OutVF:
		maxColLen := 0
		for _, col := range res.Columns {
			if len(col) > maxColLen {
				maxColLen = len(col)
			}
		}

		for idx, row := range res.Rows {
			fmt.Fprintf(w, "---[%2d]------------------------%s", idx+1, eol)
			for i, col := range res.Columns {
				valStr := FormatValue(row[i], opts.OutNull, opts.OutNullSet)
				fmt.Fprintf(w, "%*s | %s%s", maxColLen, col, valStr, eol)
			}
		}

	case OutAT, OutMD:
		widths := make([]int, len(res.Columns))
		isNumCol := make([]bool, len(res.Columns))
		for i := range isNumCol {
			isNumCol[i] = true
		}

		for i, col := range res.Columns {
			widths[i] = len(col)
		}

		for _, row := range res.Rows {
			for i, val := range row {
				valStr := FormatValue(val, opts.OutNull, opts.OutNullSet)
				if len(valStr) > widths[i] {
					widths[i] = len(valStr)
				}
				if val != nil {
					switch val.(type) {
					case int, int64, float64:
						// numeric
					default:
						valStrTrim := strings.TrimSpace(valStr)
						if _, err := strconv.ParseFloat(valStrTrim, 64); err != nil {
							isNumCol[i] = false
						}
					}
				}
			}
		}

		var lineBuf bytes.Buffer

		if outFormat == OutAT {
			// Top border
			lineBuf.WriteString("+")
			for _, w := range widths {
				lineBuf.WriteString(strings.Repeat("-", w+2) + "+")
			}
			lineBuf.WriteString(eol)

			// Header
			lineBuf.WriteString("|")
			for i, col := range res.Columns {
				padLeft := (widths[i] - len(col)) / 2
				padRight := widths[i] - len(col) - padLeft
				lineBuf.WriteString(" " + strings.Repeat(" ", padLeft) + col + strings.Repeat(" ", padRight) + " |")
			}
			lineBuf.WriteString(eol)

			// Header border
			lineBuf.WriteString("+")
			for _, w := range widths {
				lineBuf.WriteString(strings.Repeat("-", w+2) + "+")
			}
			lineBuf.WriteString(eol)

			// Rows
			for _, row := range res.Rows {
				lineBuf.WriteString("|")
				for i, val := range row {
					valStr := FormatValue(val, opts.OutNull, opts.OutNullSet)
					if isNumCol[i] {
						// Right aligned
						padLeft := widths[i] - len(valStr)
						lineBuf.WriteString(" " + strings.Repeat(" ", padLeft) + valStr + " |")
					} else {
						// Left aligned
						padRight := widths[i] - len(valStr)
						lineBuf.WriteString(" " + valStr + strings.Repeat(" ", padRight) + " |")
					}
				}
				lineBuf.WriteString(eol)
			}

			// Bottom border
			lineBuf.WriteString("+")
			for _, w := range widths {
				lineBuf.WriteString(strings.Repeat("-", w+2) + "+")
			}
			lineBuf.WriteString(eol)

		} else if outFormat == OutMD {
			// Header
			lineBuf.WriteString("|")
			for i, col := range res.Columns {
				padLeft := (widths[i] - len(col)) / 2
				padRight := widths[i] - len(col) - padLeft
				lineBuf.WriteString(" " + strings.Repeat(" ", padLeft) + col + strings.Repeat(" ", padRight) + " |")
			}
			lineBuf.WriteString(eol)

			// Header border
			lineBuf.WriteString("|")
			for _, w := range widths {
				lineBuf.WriteString(strings.Repeat("-", w+2) + "|")
			}
			lineBuf.WriteString(eol)

			// Rows
			for _, row := range res.Rows {
				lineBuf.WriteString("|")
				for i, val := range row {
					valStr := FormatValue(val, opts.OutNull, opts.OutNullSet)
					if isNumCol[i] {
						padLeft := widths[i] - len(valStr)
						lineBuf.WriteString(" " + strings.Repeat(" ", padLeft) + valStr + " |")
					} else {
						padRight := widths[i] - len(valStr)
						lineBuf.WriteString(" " + valStr + strings.Repeat(" ", padRight) + " |")
					}
				}
				lineBuf.WriteString(eol)
			}
		}

		w.Write(lineBuf.Bytes())
	}

	return nil
}
EOF"}

