package main

import (
	"fmt"
	"os"
	"strings"
)

func AnalyzeFile(filename string, opts ImportOptions, flagsPrefix string, debug bool) error {
	r, actualName, err := OpenInputFile(filename)
	if err != nil {
		return err
	}
	defer r.Close()

	parsed, err := ReadTableData(r, actualName, opts, debug)
	if err != nil {
		return err
	}

	if len(parsed.ColNames) == 0 {
		return fmt.Errorf("no columns found in %s", filename)
	}

	fileTypeStr := "CSV"
	inFmt := opts.InFormat
	if !opts.HasInFmt && opts.Guess {
		inFmt = GuessInputFormat(filename)
	}
	switch inFmt {
	case FormatCSV:
		fileTypeStr = "CSV"
	case FormatTSV:
		fileTypeStr = "TSV"
	case FormatPSV:
		fileTypeStr = "PSV"
	case FormatLTSV:
		fileTypeStr = "LTSV"
	case FormatJSON:
		fileTypeStr = "JSON"
	case FormatYAML:
		fileTypeStr = "YAML"
	case FormatTBLN:
		fileTypeStr = "TBLN"
	case FormatTEXT:
		fileTypeStr = "TEXT"
	case FormatWIDTH:
		fileTypeStr = "WIDTH"
	}

	cols := parsed.ColNames
	sampleRow := make([]interface{}, len(cols))
	if len(parsed.Rows) > 0 {
		sampleRow = parsed.Rows[0]
	}

	// 1. Table info
	fmt.Printf("The table name is %s.\n", filename)
	fmt.Printf("The file type is %s.\n\n", fileTypeStr)

	// 2. Data types
	fmt.Println("Data types:")
	typeCols := []string{"column name", "type"}
	typeRows := make([][]interface{}, len(cols))
	for i, c := range cols {
		typeRows[i] = []interface{}{c, "text"}
	}
	typeResult := &QueryResult{Columns: typeCols, Rows: typeRows}
	ExportResult(typeResult, ExportOptions{OutFormat: OutAT})
	fmt.Println()

	// 3. Data samples
	fmt.Println("Data samples:")
	sampleResult := &QueryResult{Columns: cols, Rows: parsed.Rows}
	if len(parsed.Rows) > 1 {
		sampleResult.Rows = parsed.Rows[:1]
	}
	ExportResult(sampleResult, ExportOptions{OutFormat: OutAT})
	fmt.Println()

	// 4. Examples
	fmt.Println("Examples:")
	PrintExamples(filename, cols, sampleRow, flagsPrefix)

	return nil
}

func AnalyzeFileExamplesOnly(filename string, opts ImportOptions, flagsPrefix string, debug bool) error {
	r, actualName, err := OpenInputFile(filename)
	if err != nil {
		return err
	}
	defer r.Close()

	parsed, err := ReadTableData(r, actualName, opts, debug)
	if err != nil {
		return err
	}

	if len(parsed.ColNames) == 0 {
		return fmt.Errorf("no columns found in %s", filename)
	}

	cols := parsed.ColNames
	sampleRow := make([]interface{}, len(cols))
	if len(parsed.Rows) > 0 {
		sampleRow = parsed.Rows[0]
	}

	PrintExamples(filename, cols, sampleRow, flagsPrefix)
	return nil
}

func PrintExamples(filename string, cols []string, sampleRow []interface{}, flagsPrefix string) {
	colsStr := strings.Join(cols, ", ")
	firstCol := cols[0]
	firstVal := ""
	if len(sampleRow) > 0 && sampleRow[0] != nil {
		firstVal = fmt.Sprintf("%v", sampleRow[0])
	}

	prefix := "./executable"
	if len(os.Args) > 0 {
		prefix = os.Args[0]
	}
	if flagsPrefix != "" {
		prefix = prefix + " " + flagsPrefix
	}

	fmt.Printf("%s \"SELECT %s FROM %s\"\n", prefix, colsStr, filename)
	fmt.Printf("%s \"SELECT %s FROM %s WHERE %s = '%s'\"\n", prefix, colsStr, filename, firstCol, firstVal)
	fmt.Printf("%s \"SELECT %s, count(%s) FROM %s GROUP BY %s\"\n", prefix, colsStr, firstCol, filename, firstCol)
	fmt.Printf("%s \"SELECT %s FROM %s ORDER BY %s LIMIT 10\"\n", prefix, colsStr, filename, firstCol)
}
EOF"}

