		flagItbln  = fs.Bool("itbln", false, "")
		flagItext  = fs.Bool("itext", false, "")
		flagIwidth = fs.Bool("iwidth", false, "")
		flagIyaml  = fs.Bool("iyaml", false, "")

		// Input options
		flagId    = fs.String("id", ",", "")
		flagIh    = fs.Bool("ih", false, "")
		flagIjq   = fs.String("ijq", "", "")
