		flagInull = fs.String("inull", "", "")
		flagInum  = fs.Bool("inum", false, "")
		flagIr    = fs.Int("ir", 1, "")
		flagIs    = fs.Int("is", 0, "")

		// Output formats
		flagOat   = fs.Bool("oat", false, "")
		flagOcsv  = fs.Bool("ocsv", false, "")
		flagOjson = fs.Bool("ojson", false, "")
		flagOjsonl= fs.Bool("ojsonl", false, "")
		flagOltsv = fs.Bool("oltsv", false, "")
		flagOmd   = fs.Bool("omd", false, "")
		flagOraw  = fs.Bool("oraw", false, "")
		flagOtbln = fs.Bool("otbln", false, "")
		flagOvf   = fs.Bool("ovf", false, "")
		flagOyaml = fs.Bool("oyaml", false, "")

		// Output options
		flagOaq    = fs.Bool("oaq", false, "")
		flagOcrlf  = fs.Bool("ocrlf", false, "")
		flagOd     = fs.String("od", ",", "")
		flagOh     = fs.Bool("oh", false, "")
		flagOnowrap= fs.Bool("onowrap", false, "")
		flagOnull  = fs.String("onull", "", "")
		flagOq     = fs.String("oq", "\"", "")
		flagOut    = fs.String("out", "", "")
		flagNoGuess= fs.Bool("out-without-guess", false, "")
		flagOz     = fs.String("oz", "", "")
	)

	err := fs.Parse(os.Args[1:])
	if err != nil {
		fs.Usage()
		os.Exit(2)
	}

	if *flagVersion {
		fmt.Println("trdsql version devel")
		os.Exit(0)
	}

