	// Load config
	explicitConfig := false
	for _, arg := range os.Args[1:] {
		if strings.HasPrefix(arg, "-config") {
			explicitConfig = true
			break
		}
	}

	cfg, err := LoadConfig(*flagConfig, explicitConfig, debug)
	if err != nil {
		logWithTime(fmt.Sprintf("ERROR: %s", err))
		os.Exit(1)
	}

	if *flagDbList {
		if len(cfg.Database) > 0 {
			for name, setting := range cfg.Database {
				fmt.Printf("%s:%s\n", name, setting.Driver)
			}
		}
		os.Exit(0)
	}

	// Prepare InputOptions
	inFmt := FormatCSV
	hasInFmt := false
	if *flagIltsv {
		inFmt = FormatLTSV
		hasInFmt = true
	} else if *flagIjson {
		inFmt = FormatJSON
		hasInFmt = true
	} else if *flagIyaml {
		inFmt = FormatYAML
		hasInFmt = true
	} else if *flagItbln {
		inFmt = FormatTBLN
		hasInFmt = true
	} else if *flagItext {
		inFmt = FormatTEXT
		hasInFmt = true
	} else if *flagIwidth {
		inFmt = FormatWIDTH
		hasInFmt = true
	} else if *flagIcsv {
		inFmt = FormatCSV
		hasInFmt = true
	}

