		if strings.HasPrefix(arg, "-inull") {
			inNullSet = true
			break
		}
	}

	inOpts := ImportOptions{
		InFormat:  inFmt,
		HasInFmt:  hasInFmt,
		Delimiter: *flagId,
		Header:    *flagIh,
		Jq:        *flagIjq,
		LimitRead: *flagIlr,
		InNull:    *flagInull,
		InNullSet: inNullSet,
		AddNum:    *flagInum,
		PreRead:   *flagIr,
		Skip:      *flagIs,
		Guess:     *flagIg != "false",
	}

	// Build flags prefix for analyze
	var flagsPrefix []string
	if *flagIh {
		flagsPrefix = append(flagsPrefix, "-ih")
	}
	if *flagIltsv {
		flagsPrefix = append(flagsPrefix, "-iltsv")
	} else if *flagIjson {
		flagsPrefix = append(flagsPrefix, "-ijson")
	} else if *flagIyaml {
		flagsPrefix = append(flagsPrefix, "-iyaml")
	}
	if *flagId != "," && *flagId != "" {
		flagsPrefix = append(flagsPrefix, fmt.Sprintf("-id \"%s\"", *flagId))
	}

	// Check Analyze -a / -A
	analyzeFile := ""
	isAOnly := false

	if *flagA_low != "" {
		analyzeFile = *flagA_low
	} else if *flagA != "" {
		analyzeFile = *flagA
		isAOnly = true
	}

