		if dbSetting.Driver != "" {
			driver = dbSetting.Driver
		}
		if dbSetting.Dsn != "" {
			dsn = dbSetting.Dsn
		}
	}

	if *flagDriver != "" {
		driver = *flagDriver
	}
	if *flagDsn != "" {
		dsn = *flagDsn
	}

	if debug {
		logWithTime(fmt.Sprintf("driver: %s, dsn: %s", driver, dsn))
	}

