		os.Exit(2)
	}

	if sqlQuery == "" {
		fmt.Print(HelpText)
		os.Exit(2)
	}

	// Resolve Driver & DSN
	driver := "sqlite3"
	dsn := ":memory:"

	dbName := *flagDb
	if dbName == "" {
		dbName = cfg.Db
	}

	if dbSetting, ok := cfg.Database[dbName]; ok {
		if dbSetting.Driver != "" {
			driver = dbSetting.Driver
		}
		if dbSetting.Dsn != "" {
			dsn = dbSetting.Dsn
		}
	}

	if *flagDriver != "" {
		driver = *flagDriver
	}
	if *flagDsn != "" {
		dsn = *flagDsn
	}

	if debug {
		logWithTime(fmt.Sprintf("driver: %s, dsn: %s", driver, dsn))
	}

	if driver != "sqlite3" && driver != "sqlite3_ext" {
		logWithTime(fmt.Sprintf("connect: sql: unknown driver \"%s\" (forgotten import?)", driver))
		os.Exit(1)
	}

	db, err := OpenDB(dsn)
	if err != nil {
		logWithTime(fmt.Sprintf("connect: %s", err))
		os.Exit(1)
	}
	defer db.Close()

	// Import Tables
	transformedSQL, err := ImportTables(db, sqlQuery, inOpts, debug)
	if err != nil {
		logWithTime(fmt.Sprintf("%s", err))
		os.Exit(1)
	}

	if debug {
		logWithTime(transformedSQL)
	}

	// Execute Query
	queryResult, err := db.Query(transformedSQL)
	if err != nil {
		logWithTime(fmt.Sprintf("export: %s", err))
		os.Exit(1)
	}

	// Output Formatting
	outFmt := OutCSV
	if *flagOltsv {
		outFmt = OutLTSV
	} else if *flagOjson {
		outFmt = OutJSON
	} else if *flagOjsonl {
		outFmt = OutJSONL
	} else if *flagOmd {
		outFmt = OutMD
	} else if *flagOat {
		outFmt = OutAT
	} else if *flagOvf {
		outFmt = OutVF
	} else if *flagOraw {
		outFmt = OutRAW
	} else if *flagOtbln {
		outFmt = OutTBLN
	} else if *flagOyaml {
		outFmt = OutYAML
	} else if *flagOcsv {
		outFmt = OutCSV
	}

	outNullSet := false
	for _, arg := range os.Args[1:] {
		if strings.HasPrefix(arg, "-onull") {
			outNullSet = true
			break
		}
	}

	outOpts := ExportOptions{
		OutFormat:  outFmt,
		AllQuotes:  *flagOaq,
		CRLF:       *flagOcrlf,
		Delimiter:  *flagOd,
		Header:     *flagOh,
		NoWrap:     *flagOnowrap,
		OutNull:    *flagOnull,
		OutNullSet: outNullSet,
		QuoteChar:  *flagOq,
		OutFile:    *flagOut,
		NoGuess:    *flagNoGuess,
		Compress:   *flagOz,
	}

	if err := ExportResult(queryResult, outOpts); err != nil {
		logWithTime(fmt.Sprintf("export error: %s", err))
		os.Exit(1)
	}
}
EOF"}
